{"function": "() => {
    const article = document.querySelector('article');
    const text = article ? article.innerText : document.body.innerText;
    // Split into paragraphs or sentences (simple split by newline)
    const paragraphs = text.split('\n\n');
    const nanoKeywords = [
        'nano-diamond',
        'nanocrystalline diamond',
        'NCD',
        'quantum dot',
        'QD',
        'silicon nanocrystal',
        'SiNC',
        'nanocrystal',
        'nanoparticle',
        'nanocomposite',
        'nanomaterial',
        'nanostructure',
        'nanocolumn',
        'nano',
        'quantum dots',
        'SiNCs',
        'QDs'
    ];
    const matches = [];
    paragraphs.forEach((para, idx) => {
        const lowerPara = para.toLowerCase();
        nanoKeywords.forEach(keyword => {
            if (lowerPara.includes(keyword.toLowerCase())) {
                // Extract sentence(s) containing keyword
                const sentences = para.split(/[.!?]+/);
                sentences.forEach(sent => {
                    if (sent.toLowerCase().includes(keyword.toLowerCase())) {
                        matches.push({
                            keyword: keyword,
                            sentence: sent.trim(),
                            paragraphIndex: idx
                        });
                    }
                });
            }
        });
    });
    // Deduplicate similar matches
    const uniqueMatches = [];
    const seen = new Set();
    matches.forEach(m => {
        const key = m.keyword + '|' + m.sentence;
        if (!seen.has(key)) {
            seen.add(key);
            uniqueMatches.push(m);
        }
    });
    return uniqueMatches;
}"}

